    @net.neoforged.bus.api.SubscribeEvent public static void checkpoint(net.neoforged.neoforge.event.server.ServerStartedEvent e){if(!(e.getServer() instanceof GameTestServer))return;previous=null;long last=ChurchLifeData.get(e.getServer()).activities().stream().mapToLong(ChurchActivity::updated).max().orElse(0);e.getServer().getWorldData().overworldData().setGameTime(Math.max(e.getServer().overworld().getGameTime(),last+1));if(!Boolean.getBoolean("sagadyssey.phase4.requireRestart"))return;
        try{previous=NbtIo.readCompressed(e.getServer().getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("phase8-restart-checkpoint.nbt"),NbtAccounter.unlimitedHeap());e.getServer().getWorldData().overworldData().setGameTime(Math.max(e.getServer().overworld().getGameTime(),previous.getLong("Time")+1));}catch(Exception x){throw new IllegalStateException("phase8 mandatory previous-process checkpoint",x);}}
