    public static void mandatoryNewProcessResumesOriginalScribeWithoutDuplicateCopy(GameTestHelper h){if(!Boolean.getBoolean("sagadyssey.phase4.requireRestart")){h.succeed();return;}h.assertTrue(previous!=null,"original stage8 checkpoint required");var pos=BlockPos.of(previous.getLong("Position"));force(h.getLevel(),pos.offset(-16,0,-16),pos.offset(40,0,16));boolean[] resumed={false};h.succeedWhen(()->{var host=(NpcBase)h.getLevel().getEntity(previous.getUUID("Host"));h.assertTrue(host!=null,"same original scribe body loaded from disk");var d=ChurchLifeData.get(host.getServer());var a=d.activity(previous.getUUID("Activity"));var t=ReligionData.get(host.getServer()).temple(previous.getUUID("Temple"));var box=SupplyFlowService.container(host.getServer(),t.treasury());
            if(!resumed[0]){h.assertTrue(a.work()==previous.getInt("Work")&&count(box,"paper")==6,"saved actual partial progress and original materials");host.setCommand(NpcCommand.WORK);resumed[0]=true;}
            h.assertTrue(d.activity(a.id()).stage()==ChurchActivity.Stage.COMPLETED&&count(box,"paper")==3&&count(box,"ink_sac")==1&&count(box,"leather")==1,"one manuscript after true process restart");h.assertTrue(ChurchLifeService.physicalPresent(host.getServer(),d.record(a.id())),"same identifiable output book");});}
