    public static void lateStudentDoesNotReceiveAnEntireCourseAtSettlement(GameTestHelper h){var f=fixture(h,TempleRecord.Role.SCRIBE_TEACHER);var r=source(h,f,ChurchRecord.Access.PUBLIC_TEXT);var late=npc(h,new BlockPos(15,1,8),false);var a=schedule(h,f,ChurchActivity.Kind.LESSON,r.id(),List.of(f.guest(),late),1,500);ChurchLifeService.consent(f.host().getServer(),a.id(),f.guest());h.succeedWhen(()->{var d=ChurchLifeData.get(f.host().getServer());if(d.activity(a.id()).work()>=20&&!d.activity(a.id()).consent().contains(late.getCharacterId()))ChurchLifeService.consent(late.getServer(),a.id(),late);h.assertTrue(d.activity(a.id()).stage()==ChurchActivity.Stage.COMPLETED,"lesson done");h.assertTrue(d.exposure(a.id(),late.getCharacterId())<40&&KnowledgeStateData.get(late.getServer()).beliefsAbout(late.getCharacterId(),f.temple().id()).stream().noneMatch(b->b.provenanceChain().contains(r.id())),"late arrival is not full teaching credit");});}
